/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-item {
  font-family: var(--ui-font-family, inherit);
  color: var(--ui-text, #171717);
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.01em);
  box-sizing: border-box;
}
:where([data-moru-registry]) .ui-item {
  --ui-size-height: var(--ui-control-height-md, var(--ui-control-height, 40px));
  --ui-size-padding-x: var(--ui-control-padding-x-md, 12px);
  --ui-size-icon: var(--ui-icon-size-md, 16px);
  --ui-resolved-control-height: max(
    var(--ui-size-height),
    calc(
      max(
          var(--ui-type-label-size, 14px) * var(--ui-type-label-line-height, 1.45),
          var(--ui-size-icon)
        ) +
        var(--ui-border-width, 1px) * 2 + var(--ui-space, 4px) * 2
    )
  );
}
:where([data-moru-registry]) .ui-item[data-size='sm'] {
  --ui-size-height: var(--ui-control-height-sm, 32px);
  --ui-size-padding-x: var(--ui-control-padding-x-sm, 10px);
  --ui-size-icon: var(--ui-icon-size-sm, 14px);
}
:where([data-moru-registry]) .ui-item[data-size='lg'] {
  --ui-size-height: var(--ui-control-height-lg, 48px);
  --ui-size-padding-x: var(--ui-control-padding-x-lg, 16px);
  --ui-size-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-item {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  min-width: 0;
  gap: var(--ui-control-gap, 8px);
  padding: calc(var(--ui-size-padding-x) + var(--ui-space, 4px));
  border: var(--ui-border-width, 1px) solid transparent;
  border-radius: calc(var(--ui-radius, 6px) + 4px);
}
:where([data-moru-registry]) .ui-item[data-variant='outline'] {
  border-color: var(--ui-border, #e8e8e4);
  background: var(--ui-input-bg, #f0f0ed);
}
:where([data-moru-registry]) .ui-item[data-variant='muted'] {
  background: var(--ui-surface-hover, #f3f3f1);
}
:where([data-moru-registry]) .ui-item-group {
  display: flex;
  flex-direction: column;
  gap: var(--ui-field-gap, 6px);
  min-width: 0;
}
:where([data-moru-registry]) .ui-item-media {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--ui-muted, #6e6e6b);
}
:where([data-moru-registry]) .ui-item-media > svg {
  width: calc(var(--ui-size-icon) + 4px);
  height: calc(var(--ui-size-icon) + 4px);
}
:where([data-moru-registry]) .ui-item-content {
  flex: 1 1 80px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--ui-field-gap, 6px) / 2);
}
:where([data-moru-registry]) .ui-item-title {
  font: inherit;
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-item-description {
  margin: 0;
  color: var(--ui-muted, #6e6e6b);
  font-size: var(--ui-type-caption-size, 12px);
  font-weight: var(--ui-type-caption-weight, 400);
  line-height: var(--ui-type-caption-line-height, 1.5);
  letter-spacing: var(--ui-type-caption-letter-spacing, 0em);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-item-actions {
  display: flex;
  align-items: center;
  gap: var(--ui-control-gap, 8px);
  flex-wrap: wrap;
}
:where([data-moru-registry]) .ui-item-separator {
  width: 100%;
  margin: 0;
  border: 0;
  border-block-start: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
}

'use client'
